typedef unsigned long long big_int;

class string_buf
{
public:
  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

  inline int compare(const char *str) const
  {
    int i;
    const char *a = reinterpret_cast<const char *>(data);;
    for (i = 0; i < char_length; i++) {
      if (str[i] == '\0') return -1;
      if (a[i] == str[i]) continue;
      if (str[i] > a[i]) return 1;
      if (str[i] < a[i]) return -1;
    }
    if (str[i] == '\0') return 0;
    return 1;
  }
};

class stringx
{
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  ~stringx();
  stringx &operator=(const stringx &cp);
  friend inline bool operator==(const stringx& lhs, const char *rhs);
  friend inline bool operator!=(const stringx& lhs, const char *rhs);
};

inline bool operator==(const stringx& lhs, const char *rhs)
{
  return (lhs.my_buf->compare(rhs) == 0);
}

inline bool operator!=(const stringx& lhs, const char *rhs)
{
  return !lhs.my_buf->compare(rhs);
}

template <class T> class singleton_ptr
{
  T *p;
public:
  operator T*() const { return p; }
};

class singleton { public: virtual ~singleton(); };

class os_developer_options : public singleton
{
public:
  enum flags_t { FLAG_STASH_ONLY, FLAG_NO_CD };
  bool is_flagged(flags_t flag) const { return flags[flag]; }
  static os_developer_options *inst() { return instance; }
private:
  bool flags[2];
  static singleton_ptr<os_developer_options> instance;
};

asm(".equ _20os_developer_options$instance,0x0045B180");

struct sceCdlFILE { unsigned int lsn, size; char name[16]; unsigned char date[8]; };

class os_file
{
public:
  enum mode_flags { FILE_READ = 1 };
  os_file();
  ~os_file();
  void close();
  static bool file_exists(const stringx& name);
private:
  stringx name;
  int flags;
  bool opened;
  bool eof;
  bool from_cd;
  union { int host; sceCdlFILE cd; } io;
  int curr_fp;
  bool try_to_open_from_cd();
  bool try_to_open_from_disk();
};

bool os_file::file_exists(const stringx& _name)
{
//  proftimer_file_exists.start();
  os_file foo;
  int ret = false;

  foo.name = _name;
  foo.flags = FILE_READ;

  if (_name != "GAME.INI" && _name != "tricks.dat" && !os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_CD))
    ret = foo.try_to_open_from_cd();
  else if (_name == "GAME.INI" || _name == "tricks.dat")
    ret = foo.try_to_open_from_cd();
  if (ret == false)
    ret = foo.try_to_open_from_disk();

  if (ret)
  {
    foo.close();
    return true;
  }
  return false;

//  proftimer_file_exists.stop();
}
